WITH n AS (SELECT b.mktcode,b.tgtcode,AVG(e.ZJLXMainNetTur) AS net_avg FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_ext` AS e ON e.mktcode=b.mktcode AND e.tgtcode=b.tgtcode AND e.bizdate=b.bizdate WHERE b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode), t AS (SELECT b.mktcode,b.tgtcode,AVG(b.turnover) AS turnover_avg FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS a INNER JOIN n ON n.mktcode=a.mktcode AND n.tgtcode=a.tgtcode INNER JOIN t ON t.mktcode=a.mktcode AND t.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14' AND n.net_avg/NULLIF(t.turnover_avg,0)<20;
